<?php
require __DIR__.'/db.php'; require_admin(); require __DIR__.'/layout.php'; require __DIR__.'/user-invite-lib.php'; ensure_user_invite_schema($pdo);
$id=isset($_GET['id'])?(int)$_GET['id']:0; $row=array('username'=>'','email'=>'','display_name'=>'','role'=>'user','is_active'=>0);
if($id){$st=$pdo->prepare('SELECT * FROM mp_users WHERE id=?');$st->execute(array($id));$row=$st->fetch();if(!$row){http_response_code(404);exit('Uživatel nenalezen.');}}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$username=trim($_POST['username']??'');$display=trim($_POST['display_name']??'');$email=trim($_POST['email']??'');$role=(isset($_POST['role'])&&$_POST['role']==='admin')?'admin':'user';$active=isset($_POST['is_active'])?1:0;$password=$_POST['password']??'';
try{if($username==='')throw new Exception('Vyplňte uživatelské jméno.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('Zadejte platnou e-mailovou adresu.');if($id&&$password!==''&&strlen($password)<8)throw new Exception('Heslo musí mít alespoň 8 znaků.');
if($id){$old=$row;if((int)$id===(int)$_SESSION['user_id']&&(!$active||$role!=='admin'))throw new Exception('U svého právě přihlášeného administrátorského účtu nelze odebrat roli ani jej deaktivovat.');if($old['role']==='admin'&&(int)$old['is_active']===1&&($role!=='admin'||!$active)){$cnt=(int)$pdo->query("SELECT COUNT(*) FROM mp_users WHERE role='admin' AND is_active=1")->fetchColumn();if($cnt<=1)throw new Exception('Poslednímu aktivnímu administrátorovi nelze odebrat oprávnění.');}if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$st=$pdo->prepare('UPDATE mp_users SET username=?,email=?,display_name=?,role=?,is_active=?,password_hash=? WHERE id=?');$st->execute(array($username,$email?:null,$display,$role,$active,$hash,$id));}else{$st=$pdo->prepare('UPDATE mp_users SET username=?,email=?,display_name=?,role=?,is_active=? WHERE id=?');$st->execute(array($username,$email?:null,$display,$role,$active,$id));}if((int)$id===(int)$_SESSION['user_id']){$_SESSION['username']=$username;$_SESSION['display_name']=$display;$_SESSION['role']=$role;}}
else{if($email==='')throw new Exception('Pro odeslání pozvánky vyplňte e-mail.');$placeholder=password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT);$st=$pdo->prepare('INSERT INTO mp_users(username,email,password_hash,display_name,role,is_active) VALUES(?,?,?,?,?,0)');$st->execute(array($username,$email,$placeholder,$display,$role));$newId=(int)$pdo->lastInsertId();$token=create_invitation($pdo,$newId);$sent=send_user_invitation($email,$username,$display,$token);redirect_to('users.php?invited=1&mail='.($sent?'1':'0'));}redirect_to('users.php?saved=1');}
catch(PDOException $e){$error='Uživatelské jméno nebo e-mail už pravděpodobně existuje.';}catch(Exception $e){$error=$e->getMessage();}$row=array('username'=>$username,'email'=>$email,'display_name'=>$display,'role'=>$role,'is_active'=>$active);}
page_top($id?'Upravit uživatele':'Nový uživatel','users');?>
<div class="pagehead"><div><h1><?php echo $id?'Upravit uživatele':'Nový uživatel'; ?></h1><div class="sub">Přístupový účet do MĚŘENÍ PRO.</div></div><a class="btn secondary" href="users.php">Zpět</a></div><?php if($error): ?><div class="notice error"><?php echo h($error); ?></div><?php endif; ?><section class="card user-form-card"><form method="post"><input type="hidden" name="csrf" value="<?php echo h(csrf_token()); ?>"><label>Jméno</label><input name="display_name" value="<?php echo h($row['display_name']); ?>" autocomplete="name"><label>Uživatelské jméno</label><input name="username" required value="<?php echo h($row['username']); ?>" autocomplete="username"><label>E-mail</label><input name="email" type="email" <?php echo $id?'':'required'; ?> value="<?php echo h($row['email']??''); ?>" autocomplete="email"><label>Role</label><select name="role"><option value="user" <?php echo $row['role']==='user'?'selected':''; ?>>Uživatel</option><option value="admin" <?php echo $row['role']==='admin'?'selected':''; ?>>Administrátor</option></select><?php if($id): ?><label>Heslo <small class="muted">– ponechte prázdné, pokud jej nechcete měnit</small></label><input name="password" type="password" minlength="8" autocomplete="new-password"><label class="checkline"><input type="checkbox" name="is_active" value="1" <?php echo (int)$row['is_active']===1?'checked':''; ?>> Aktivní účet</label><?php else: ?><div class="notice">Uživatel si heslo nastaví sám přes jednorázovou e-mailovou pozvánku. Pozvánka platí 48 hodin.</div><?php endif; ?><div class="actions"><button class="btn" type="submit"><?php echo $id?'Uložit uživatele':'Vytvořit a odeslat pozvánku'; ?></button><a class="btn secondary" href="users.php">Zrušit</a></div></form></section><?php page_bottom(); ?>